(5925211, 863208, 30861, '<td valign="top">I love this triptych, and gave it a 7, though I fear it will run afoul of the rule that entries must be created from a single image...</td>', 'I love this triptych, and gave it a 7, though I fear it will run afoul of the rule that entries must be created from a single image...', '2010-04-01 11:00:46.000000', NULL, 1),
