INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5925231, 861790, 30049, '<td valign="top">I like the soft mood overall, although wouldn''t mind a little bit of sharpness in her face.  Also feels uncomfortable with her looking out of the frame.</td>', 'I like the soft mood overall, although wouldn''t mind a little bit of sharpness in her face.  Also feels uncomfortable with her looking out of the frame.', '2010-04-01 11:04:40.000000', NULL, 1),
(5925233, 862289, 4793, '<td valign="top">Very nice shot</td>', 'Very nice shot', '2010-04-01 11:04:53.000000', NULL, 1),
(5925234, 863892, 4793, '<td valign="top">Nice capture</td>', 'Nice capture', '2010-04-01 11:05:23.000000', NULL, 1),
(5925235, 863507, 30049, '<td valign="top">Like the water motion, a little bit too much sky IMO keeping the rock somewhat centered.  Standard Free Study sunset/landscape fare for sure.  Good luck.</td>', 'Like the water motion, a little bit too much sky IMO keeping the rock somewhat centered.  Standard Free Study sunset/landscape fare for sure.  Good luck.', '2010-04-01 11:06:13.000000', NULL, 1),
(5925236, 864112, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: What a wonderful effect - I wouldn''t be surprised if you get a validation request. I''m seeing this as a longer exposure Lensbaby shot though and it makes me want to try it! How effectively you''ve isolated your subject and the monochrome treatment suits the image well.<br/> <br/>Critical stuff: The right side of her face (our right) has an indistinct boundary that I''m not sure works - artefact between zones of blur brush and sharpen brush?<br/> <br/>Overall: A striking image and one I really like too.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: What a wonderful effect - I wouldn''t be surprised if you get a validation request. I''m seeing this as a longer exposure Lensbaby shot though and it makes me want to try it! How effectively you''ve isolated your subject and the monochrome treatment suits the image well. Critical stuff: The right side of her face (our right) has an indistinct boundary that I''m not sure works - artefact between zones of blur brush and sharpen brush? Overall: A striking image and one I really like too.', '2010-04-01 11:06:24.000000', NULL, 1),
(5925238, 859740, 4793, '<td valign="top">Yes antennas are every where you look, but we like our cell phones,etc. Nice shot.</td>', 'Yes antennas are every where you look, but we like our cell phones,etc. Nice shot.', '2010-04-01 11:06:39.000000', NULL, 1),
(5925240, 859340, 35545, '<td valign="top">I really like this shot and the processing.  IMNSHO, you could crop off a lot of the top and tighten up the composition.  I really like the diagonal line of the beam in the upper right, but other than that, there isn''t anything going on in the upper third of the shot.  7</td>', 'I really like this shot and the processing.  IMNSHO, you could crop off a lot of the top and tighten up the composition.  I really like the diagonal line of the beam in the upper right, but other than that, there isn''t anything going on in the upper third of the shot.  7', '2010-04-01 11:07:09.000000', NULL, 1),
(5925242, 861399, 30049, '<td valign="top">This would be outstanding if the panning caught the animals in focus and blurred the foreground/background only.  Ratio is a little wide - maybe add a letterbox border for balance?</td>', 'This would be outstanding if the panning caught the animals in focus and blurred the foreground/background only.  Ratio is a little wide - maybe add a letterbox border for balance?', '2010-04-01 11:07:27.000000', NULL, 1),
(5925243, 864145, 4793, '<td valign="top">Nice capture</td>', 'Nice capture', '2010-04-01 11:07:48.000000', NULL, 1),
