(5925310, 864263, 64046, '<td valign="top">Wow....amazing effect, pleasing!</td>', 'Wow....amazing effect, pleasing!', '2010-04-01 11:41:52.000000', NULL, 1),
(5925312, 863436, 105130, '<td valign="top">This evokes a real sense of calm, and I think the sepia works well. Perhaps a little burning on the clouds for a little more impact? I also don''t know why you didn''t use the maximum size of 800 pixels.</td>', 'This evokes a real sense of calm, and I think the sepia works well. Perhaps a little burning on the clouds for a little more impact? I also don''t know why you didn''t use the maximum size of 800 pixels.', '2010-04-01 11:42:32.000000', NULL, 1),
(5925314, 864256, 106109, '<td valign="top">Super shot.</td>', 'Super shot.', '2010-04-01 11:43:18.000000', NULL, 1),
(5925315, 860416, 105130, '<td valign="top">Lovely scenery and really well captured. Looks like Autumn wherever you are.</td>', 'Lovely scenery and really well captured. Looks like Autumn wherever you are.', '2010-04-01 11:44:55.000000', NULL, 1),
