(5925324, 864407, 105130, '<td valign="top">It''s gritty and grimy and the repeating lines give it impact, but just a little too dark for my personal tastes.</td>', 'It''s gritty and grimy and the repeating lines give it impact, but just a little too dark for my personal tastes.', '2010-04-01 11:51:14.000000', NULL, 1),
(5925325, 863129, 105130, '<td valign="top">The post processing is a little messy, but the soft colours compliment the style you were going for.</td>', 'The post processing is a little messy, but the soft colours compliment the style you were going for.', '2010-04-01 11:52:44.000000', NULL, 1),
