(5925333, 864136, 105130, '<td valign="top">A majestic creature, but it seems a little soft and you''ve lost some details, like you pushed it too hard which processing.</td>', 'A majestic creature, but it seems a little soft and you''ve lost some details, like you pushed it too hard which processing.', '2010-04-01 11:58:40.000000', NULL, 1),
(5925335, 864100, 4793, '<td valign="top">Nice shot</td>', 'Nice shot', '2010-04-01 11:59:43.000000', NULL, 1),
(5925336, 864241, 105130, '<td valign="top">The DOF here is seriously impressive. No idea what lens you were using, but to have got such detail in an ant is incredible, especially since the move so fast!</td>', 'The DOF here is seriously impressive. No idea what lens you were using, but to have got such detail in an ant is incredible, especially since the move so fast!', '2010-04-01 12:00:25.000000', NULL, 1),
