(5925347, 863008, 105130, '<td valign="top">Great contrast and detail, it''s an eyeopener for sure.</td>', 'Great contrast and detail, it''s an eyeopener for sure.', '2010-04-01 12:06:06.000000', NULL, 1),
(5925349, 859045, 105130, '<td valign="top">Really evocative feeling of emptiness. I like to think you came across this scene, rather than having arranged the pages beforehand.</td>', 'Really evocative feeling of emptiness. I like to think you came across this scene, rather than having arranged the pages beforehand.', '2010-04-01 12:07:18.000000', NULL, 1),
