(5927872, 863364, 105130, '<td valign="top">Funny, quirky and engaging, but looks like you''ve over-dodged her eyes somewhat.</td>', 'Funny, quirky and engaging, but looks like you''ve over-dodged her eyes somewhat.', '2010-04-02 18:24:04.000000', NULL, 1),
(5927876, 864188, 105130, '<td valign="top">Fantastic panorama with the added interest of the included wildlife. I think the crop''s just a little too narrow though, the deep blue sky would have added some nice negative space if you''d included it.</td>', 'Fantastic panorama with the added interest of the included wildlife. I think the crop''s just a little too narrow though, the deep blue sky would have added some nice negative space if you''d included it.', '2010-04-02 18:25:24.000000', NULL, 1),
(5927877, 864182, 105130, '<td valign="top">It''s a nice sunrise/sunset, and the reflections are beautiful, but there''s no real detail anywhere to catch the viewer''s attention.</td>', 'It''s a nice sunrise/sunset, and the reflections are beautiful, but there''s no real detail anywhere to catch the viewer''s attention.', '2010-04-02 18:26:28.000000', NULL, 1),
(5927879, 864100, 105130, '<td valign="top">If this had been a couple of 100ths faster you''d really have nailed it. The shape of the wings and positioning of the heron in the photo are spot on though.</td>', 'If this had been a couple of 100ths faster you''d really have nailed it. The shape of the wings and positioning of the heron in the photo are spot on though.', '2010-04-02 18:28:03.000000', NULL, 1),
(5927884, 863652, 105130, '<td valign="top">While there''s nothing technically wrong with the photo (focus, depth of field, exposure, colours are all great), it is ''just'' a pet shot. Perhaps a lower angle would help add more interest?</td>', 'While there''s nothing technically wrong with the photo (focus, depth of field, exposure, colours are all great), it is ''just'' a pet shot. Perhaps a lower angle would help add more interest?', '2010-04-02 18:30:07.000000', NULL, 1),
(5927886, 864217, 105130, '<td valign="top">Beautiful light and a great expression you''ve captured. I would have been tempted to clean up her skin and some of the fluff on her jumper though.</td>', 'Beautiful light and a great expression you''ve captured. I would have been tempted to clean up her skin and some of the fluff on her jumper though.', '2010-04-02 18:31:38.000000', NULL, 1),
(5927888, 864275, 105130, '<td valign="top">Another delicate sunset and well exposed, but there''s no real focal point of interest.</td>', 'Another delicate sunset and well exposed, but there''s no real focal point of interest.', '2010-04-02 18:32:27.000000', NULL, 1),
(5927889, 863819, 105130, '<td valign="top">I think the composition could use some work. The intruding tree branch on the left and the bottom part of the photo really detract from what could have been a majestic view.</td>', 'I think the composition could use some work. The intruding tree branch on the left and the bottom part of the photo really detract from what could have been a majestic view.', '2010-04-02 18:33:50.000000', NULL, 1),
(5927890, 863921, 105130, '<td valign="top">Great light, and I''m sure the bride will be very happy with the result, but the excessive tilt and the other girl''s expression don''t work for me.</td>', 'Great light, and I''m sure the bride will be very happy with the result, but the excessive tilt and the other girl''s expression don''t work for me.', '2010-04-02 18:35:36.000000', NULL, 1),
(5927892, 864129, 105130, '<td valign="top">My cats do this all the time, but this is slightly more impressive. Great colours and definition on the tiger, and the humourous title helps tie everything together!</td>', 'My cats do this all the time, but this is slightly more impressive. Great colours and definition on the tiger, and the humourous title helps tie everything together!', '2010-04-02 18:36:47.000000', NULL, 1),
(5927894, 863509, 105130, '<td valign="top">That looks like a really lovely place to while away a summer''s afternoon. Soft and delicate, and the cable is my only main niggle.</td>', 'That looks like a really lovely place to while away a summer''s afternoon. Soft and delicate, and the cable is my only main niggle.', '2010-04-02 18:38:21.000000', NULL, 1),
