(5927967, 863870, 65234, '<td valign="top">They''re rather lovely in B&amp;W!  I''ll have to try that sometime.</td>', 'They''re rather lovely in B&W!  I''ll have to try that sometime.', '2010-04-02 19:41:53.000000', NULL, 1),
(5927968, 864216, 65234, '<td valign="top">Is that one in the back getting orders from someone?  ''Cuz the rest of them look ready to attack!</td>', 'Is that one in the back getting orders from someone?  ''Cuz the rest of them look ready to attack!', '2010-04-02 19:43:39.000000', NULL, 1),
(5927970, 864346, 65234, '<td valign="top">I find this really intriguing!  Everything seems to be in motion except the  cows.</td>', 'I find this really intriguing!  Everything seems to be in motion except the  cows.', '2010-04-02 19:46:37.000000', NULL, 1),
(5927972, 863224, 65234, '<td valign="top">That''s pretty amazing to see!</td>', 'That''s pretty amazing to see!', '2010-04-02 19:48:15.000000', NULL, 1),
(5927974, 863392, 65234, '<td valign="top">LOL!  Fabulous title :-)  I think I would have been amused by this, anyway, but the title just makes it that much more enjoyable.</td>', 'LOL!  Fabulous title :-)  I think I would have been amused by this, anyway, but the title just makes it that much more enjoyable.', '2010-04-02 19:49:36.000000', NULL, 1),
(5927977, 863751, 65234, '<td valign="top">An awful lot of competing colors here, which to me detract from focussing on her face.  I think this one would be much more flattering in B&amp;W.  I do like that raised eyebrow.</td>', 'An awful lot of competing colors here, which to me detract from focussing on her face.  I think this one would be much more flattering in B&W.  I do like that raised eyebrow.', '2010-04-02 19:51:55.000000', NULL, 1),
(5927979, 864386, 65234, '<td valign="top">Pretty little beastie, with very nice detail on his face.  The noise in the background doesn''t add anything; I''d use noise reduction or blur it out of existence.</td>', 'Pretty little beastie, with very nice detail on his face.  The noise in the background doesn''t add anything; I''d use noise reduction or blur it out of existence.', '2010-04-02 19:53:29.000000', NULL, 1),
(5927995, 861407, 75585, '<td valign="top">I almost entered an identical shot to this, this month.  Can''t wait till voting is over to share.  Very well done.</td>', 'I almost entered an identical shot to this, this month.  Can''t wait till voting is over to share.  Very well done.', '2010-04-02 20:10:37.000000', NULL, 1),
(5927998, 861790, 75585, '<td valign="top">I really love this photo - although her skin tone is a bit ashen.  Still, a lovely eerie photo</td>', 'I really love this photo - although her skin tone is a bit ashen.  Still, a lovely eerie photo', '2010-04-02 20:12:41.000000', NULL, 1),
(5928001, 864129, 75585, '<td valign="top">Hear birdie birdie birdie . . . I wanna love you, hug you and chomp you in my mouth!</td>', 'Hear birdie birdie birdie . . . I wanna love you, hug you and chomp you in my mouth!', '2010-04-02 20:13:33.000000', NULL, 1),
