(5928006, 863890, 75585, '<td valign="top">The lighting on this seems flat and unappealing to me.</td>', 'The lighting on this seems flat and unappealing to me.', '2010-04-02 20:22:58.000000', NULL, 1),
(5928007, 863981, 75585, '<td valign="top">Poor man - he has fish but no feet :-)  Also, the horizon is dipping down on the right side</td>', 'Poor man - he has fish but no feet :-)  Also, the horizon is dipping down on the right side', '2010-04-02 20:23:57.000000', NULL, 1),
(5928008, 864275, 75585, '<td valign="top">I just don''t see the interest - it is lacking the rule of thirds and a focal point; i.e., rock, boat, tree, swimmer, etc.</td>', 'I just don''t see the interest - it is lacking the rule of thirds and a focal point; i.e., rock, boat, tree, swimmer, etc.', '2010-04-02 20:24:43.000000', NULL, 1),
