(5929408, 863817, 60915, '<td valign="top">Beautiful! : )</td>', 'Beautiful! : )', '2010-04-03 22:00:45.000000', NULL, 1),
(5929409, 863356, 76335, '<td valign="top">I think I''d prefer a darker or contextual background. I do like the devil-may-care pose.</td>', 'I think I''d prefer a darker or contextual background. I do like the devil-may-care pose.', '2010-04-03 22:01:11.000000', NULL, 1),
(5929410, 860785, 57447, '<td valign="top">This almost looks not real, maybe taken with lens that distorts the secene?  I like it.</td>', 'This almost looks not real, maybe taken with lens that distorts the secene?  I like it.', '2010-04-03 22:01:26.000000', NULL, 1),
(5929411, 864244, 76335, '<td valign="top">Well, you''ve seen one, you''ve seen them all. They''re all beautiful. This one too. Beautifully done, but nothing new.</td>', 'Well, you''ve seen one, you''ve seen them all. They''re all beautiful. This one too. Beautifully done, but nothing new.', '2010-04-03 22:02:01.000000', NULL, 1),
(5929412, 863739, 60915, '<td valign="top">I like how it looks like some kind of alien! Nice work! : )</td>', 'I like how it looks like some kind of alien! Nice work! : )', '2010-04-03 22:02:13.000000', NULL, 1),
(5929415, 863506, 76335, '<td valign="top">Silly title. I''m not crazy about the processing either, but overall, it''s an effective character study.</td>', 'Silly title. I''m not crazy about the processing either, but overall, it''s an effective character study.', '2010-04-03 22:02:48.000000', NULL, 1),
(5929416, 864395, 57447, '<td valign="top">Nice work, long exposure with filter?</td>', 'Nice work, long exposure with filter?', '2010-04-03 22:03:32.000000', NULL, 1),
(5929417, 863785, 60915, '<td valign="top">Lovin'' the blurry and graininess here! : )</td>', 'Lovin'' the blurry and graininess here! : )', '2010-04-03 22:04:14.000000', NULL, 1),
(5929418, 861980, 57447, '<td valign="top">A lot of nice color captured in your entry, I am wondering what lens you used. 8 from me.</td>', 'A lot of nice color captured in your entry, I am wondering what lens you used. 8 from me.', '2010-04-03 22:05:08.000000', NULL, 1),
(5929419, 864212, 76335, '<td valign="top">This is beautiful.</td>', 'This is beautiful.', '2010-04-03 22:05:40.000000', NULL, 1),
(5929420, 864360, 57447, '<td valign="top">Good long exposure with light and dark tones captured just right.</td>', 'Good long exposure with light and dark tones captured just right.', '2010-04-03 22:06:12.000000', NULL, 1),
(5929421, 864261, 76335, '<td valign="top">Almost looks like a broken wine glass. Great!</td>', 'Almost looks like a broken wine glass. Great!', '2010-04-03 22:06:13.000000', NULL, 1),
(5929422, 864385, 60915, '<td valign="top">Wonderful street shot! : )</td>', 'Wonderful street shot! : )', '2010-04-03 22:06:52.000000', NULL, 1),
(5929424, 864222, 60915, '<td valign="top">Perfect use on the fisheye! : )</td>', 'Perfect use on the fisheye! : )', '2010-04-03 22:07:32.000000', NULL, 1),
(5929425, 862119, 57447, '<td valign="top">Beautiful place, nice entry.</td>', 'Beautiful place, nice entry.', '2010-04-03 22:07:48.000000', NULL, 1),
(5929426, 864346, 60915, '<td valign="top">fantastic blur!! : )</td>', 'fantastic blur!! : )', '2010-04-03 22:07:52.000000', NULL, 1),
(5929428, 859740, 76335, '<td valign="top">The crop to the right feels a little abrupt. Would prefer to have seen the subjects have a little more room. Unsure about the border. Ridiculous title.</td>', 'The crop to the right feels a little abrupt. Would prefer to have seen the subjects have a little more room. Unsure about the border. Ridiculous title.', '2010-04-03 22:11:00.000000', NULL, 1),
(5929429, 861323, 76335, '<td valign="top">A fantastic composition ruined by selective desat.</td>', 'A fantastic composition ruined by selective desat.', '2010-04-03 22:12:07.000000', NULL, 1),
(5929430, 861947, 57447, '<td valign="top">I feel like there''s a genie in the bottle. 7.</td>', 'I feel like there''s a genie in the bottle. 7.', '2010-04-03 22:12:14.000000', NULL, 1),
(5929431, 862926, 60915, '<td valign="top">Is that kid smoking? or is the adult giving them something else? either way cigarettes around kids isn''t good. Intriguing and disturbing image that is made more powerful by the noise and blur. It''s like we''re seeing this happen from our peripheral vision.</td>', 'Is that kid smoking? or is the adult giving them something else? either way cigarettes around kids isn''t good. Intriguing and disturbing image that is made more powerful by the noise and blur. It''s like we''re seeing this happen from our peripheral vision.', '2010-04-03 22:13:17.000000', NULL, 1),
(5929432, 864395, 60915, '<td valign="top">smoooooth! : )</td>', 'smoooooth! : )', '2010-04-03 22:13:36.000000', NULL, 1),
(5929433, 863357, 76335, '<td valign="top">The fine textures, which are really essential for this picture to deliver its impact, feel grainy. Not sure what you could have done about it. It''s still a great shot.</td>', 'The fine textures, which are really essential for this picture to deliver its impact, feel grainy. Not sure what you could have done about it. It''s still a great shot.', '2010-04-03 22:13:49.000000', NULL, 1),
