(5934752, 864240, 86218, '<td valign="top">What a beautifull place. I want to be there. Lovely shot</td>', 'What a beautifull place. I want to be there. Lovely shot', '2010-04-07 07:04:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5934754, 861184, 86218, '<td valign="top">Sky is blown out just to much for me here. Nice setting though and this needs to be taken again. Lots of potential 6</td>', 'Sky is blown out just to much for me here. Nice setting though and this needs to be taken again. Lots of potential 6', '2010-04-07 07:05:40.000000', NULL, 1),
(5934756, 864152, 86218, '<td valign="top">Beautifull colours and comp. DANG about this tree coming up from the bottom over view. It troubles me to much. I can see why you wanted this angle however. 7</td>', 'Beautifull colours and comp. DANG about this tree coming up from the bottom over view. It troubles me to much. I can see why you wanted this angle however. 7', '2010-04-07 07:07:21.000000', NULL, 1),
(5934763, 861980, 86218, '<td valign="top">Well done with this shot. It really evokes enough from a person to stare at it and have a second look. Nice comp as well. Im not sure if all the black border helps this shot or not</td>', 'Well done with this shot. It really evokes enough from a person to stare at it and have a second look. Nice comp as well. Im not sure if all the black border helps this shot or not', '2010-04-07 07:16:59.000000', NULL, 1),
(5934765, 863844, 86218, '<td valign="top">Eish...as we would say in South Africa. Very special shot and love this... 8</td>', 'Eish...as we would say in South Africa. Very special shot and love this... 8', '2010-04-07 07:17:55.000000', NULL, 1),
(5934770, 860152, 86218, '<td valign="top">What a shot! Congrats with this. Lightning speed taken by an even faster photographer</td>', 'What a shot! Congrats with this. Lightning speed taken by an even faster photographer', '2010-04-07 07:22:24.000000', NULL, 1),
(5934794, 861534, 73942, '<td valign="top">beautiful capture with some nice detail</td>', 'beautiful capture with some nice detail', '2010-04-07 07:59:27.000000', NULL, 1),
(5934796, 864266, 73942, '<td valign="top">really feels like a throwback picture, a different time, even before 1972</td>', 'really feels like a throwback picture, a different time, even before 1972', '2010-04-07 08:00:12.000000', NULL, 1),
(5934798, 863941, 73942, '<td valign="top">beautiful view, I think this image could be helped by being a little sharper, but still nice 7</td>', 'beautiful view, I think this image could be helped by being a little sharper, but still nice 7', '2010-04-07 08:01:34.000000', NULL, 1),
(5934799, 864222, 73942, '<td valign="top">interesting image, plenty to look at here</td>', 'interesting image, plenty to look at here', '2010-04-07 08:02:02.000000', NULL, 1),
(5934800, 863937, 73942, '<td valign="top">this view is well worth the hike to get up this high, nice capture</td>', 'this view is well worth the hike to get up this high, nice capture', '2010-04-07 08:02:35.000000', NULL, 1),
(5934801, 863821, 73942, '<td valign="top">I believe this is Iceland as I''ve seen this structure before.  It always makes for an interesting photo.</td>', 'I believe this is Iceland as I''ve seen this structure before.  It always makes for an interesting photo.', '2010-04-07 08:03:13.000000', NULL, 1),
(5934805, 863962, 73942, '<td valign="top">great sihouette, nice reflection, beauituful colors in the sky, this has a lot going for it</td>', 'great sihouette, nice reflection, beauituful colors in the sky, this has a lot going for it', '2010-04-07 08:08:16.000000', NULL, 1),
(5934808, 864196, 73942, '<td valign="top">nice interpretation of this popular spot</td>', 'nice interpretation of this popular spot', '2010-04-07 08:09:51.000000', NULL, 1),
(5934811, 863362, 73942, '<td valign="top">nice choice of selective desat, I like the sky color and how it matches the border</td>', 'nice choice of selective desat, I like the sky color and how it matches the border', '2010-04-07 08:11:55.000000', NULL, 1),
(5934812, 863142, 73942, '<td valign="top">beautiful colors in the sky, not sure if it''s sunrise or sunset though</td>', 'beautiful colors in the sky, not sure if it''s sunrise or sunset though', '2010-04-07 08:12:51.000000', NULL, 1),
(5934815, 864356, 73942, '<td valign="top">I like how the rocks in front give this such nice depth.</td>', 'I like how the rocks in front give this such nice depth.', '2010-04-07 08:13:23.000000', NULL, 1),
(5934816, 864403, 73942, '<td valign="top">wow, quite the veil, nice choice to convert to B&amp;W, gives is a classic kinda look</td>', 'wow, quite the veil, nice choice to convert to B&W, gives is a classic kinda look', '2010-04-07 08:13:45.000000', NULL, 1),
(5934817, 863419, 73942, '<td valign="top">excellent macro</td>', 'excellent macro', '2010-04-07 08:14:05.000000', NULL, 1),
(5934819, 863603, 73942, '<td valign="top">interesting to see this in B&amp;W but I think it works, helps the detail in the landscape more interesting</td>', 'interesting to see this in B&W but I think it works, helps the detail in the landscape more interesting', '2010-04-07 08:22:53.000000', NULL, 1),
(5934820, 862693, 73942, '<td valign="top">great macro, love all the detail</td>', 'great macro, love all the detail', '2010-04-07 08:23:11.000000', NULL, 1),
(5934821, 864219, 73942, '<td valign="top">great capture, nice interested added with the helicopter</td>', 'great capture, nice interested added with the helicopter', '2010-04-07 08:23:45.000000', NULL, 1),
(5934833, 863262, 113419, '<td valign="top">love the photo; title is a bit wordy for my taste; but I''m not scoring you on the title</td>', 'love the photo; title is a bit wordy for my taste; but I''m not scoring you on the title', '2010-04-07 08:38:26.000000', NULL, 1),
(5934836, 863225, 73942, '<td valign="top">nice action shot, this may look good in B&amp;W, give it an older feel, or sepia even</td>', 'nice action shot, this may look good in B&W, give it an older feel, or sepia even', '2010-04-07 08:41:01.000000', NULL, 1),
(5934837, 863921, 60047, '<td valign="top">Nice light management. Great detail on the bride''s dress.</td>', 'Nice light management. Great detail on the bride''s dress.', '2010-04-07 08:41:12.000000', NULL, 1),
(5934838, 860757, 113419, '<td valign="top">my opinion is that this would have been better as a black and white if it were a bit darker</td>', 'my opinion is that this would have been better as a black and white if it were a bit darker', '2010-04-07 08:41:13.000000', NULL, 1),
(5934839, 859026, 73942, '<td valign="top">yummy, would make a great stock photo / product shot</td>', 'yummy, would make a great stock photo / product shot', '2010-04-07 08:41:30.000000', NULL, 1),
(5934840, 863893, 60047, '<td valign="top">Great eyes. Great skin. Interesting composition.</td>', 'Great eyes. Great skin. Interesting composition.', '2010-04-07 08:43:25.000000', NULL, 1),
(5934841, 860785, 60047, '<td valign="top">I like the post processing. Looks like a painting.</td>', 'I like the post processing. Looks like a painting.', '2010-04-07 08:44:09.000000', NULL, 1),
(5934843, 863946, 60047, '<td valign="top">Great crop choice.</td>', 'Great crop choice.', '2010-04-07 08:44:57.000000', NULL, 1),
(5934845, 861080, 60047, '<td valign="top">A classic shot done well.</td>', 'A classic shot done well.', '2010-04-07 08:45:57.000000', NULL, 1),
(5934847, 863507, 60047, '<td valign="top">Great colors. Nice sense of movement.</td>', 'Great colors. Nice sense of movement.', '2010-04-07 08:46:42.000000', NULL, 1),
(5934850, 864276, 60047, '<td valign="top">I like the sea color here.</td>', 'I like the sea color here.', '2010-04-07 08:47:39.000000', NULL, 1),
(5934851, 863814, 60047, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2010-04-07 08:48:11.000000', NULL, 1),
(5934853, 864186, 60047, '<td valign="top">Interesting crop choice on this subject.</td>', 'Interesting crop choice on this subject.', '2010-04-07 08:49:15.000000', NULL, 1),
(5934854, 861534, 60047, '<td valign="top">I think an even tighter crop would be better. Great capture.</td>', 'I think an even tighter crop would be better. Great capture.', '2010-04-07 08:49:54.000000', NULL, 1),
(5934860, 864002, 60047, '<td valign="top">Nice grab. Great pose.</td>', 'Nice grab. Great pose.', '2010-04-07 08:52:45.000000', NULL, 1),
(5934889, 864285, 73942, '<td valign="top">nice shadowing and detail</td>', 'nice shadowing and detail', '2010-04-07 09:00:00.000000', NULL, 1),
(5934894, 864028, 73942, '<td valign="top">I love fog and early morning pictures, this ones has a nice reflection too.  Well seen.</td>', 'I love fog and early morning pictures, this ones has a nice reflection too.  Well seen.', '2010-04-07 09:03:39.000000', NULL, 1),
(5934989, 863129, 30049, '<td valign="top">Product shot approach needs to be clean.  There''s substantial evidence of post processing around the watch.  Also some grain and the sky looks purple.  Just some observations.  Good luck.</td>', 'Product shot approach needs to be clean.  There''s substantial evidence of post processing around the watch.  Also some grain and the sky looks purple.  Just some observations.  Good luck.', '2010-04-07 09:51:34.000000', NULL, 1),
(5934991, 862282, 30049, '<td valign="top">Self portrait?  :-)  Interesting how that area of purple shows up behind you (lens flare result?).</td>', 'Self portrait?  :-)  Interesting how that area of purple shows up behind you (lens flare result?).', '2010-04-07 09:52:59.000000', NULL, 1),
(5934994, 860712, 73942, '<td valign="top">great character study using photography</td>', 'great character study using photography', '2010-04-07 09:53:54.000000', NULL, 1),
(5934995, 863917, 73942, '<td valign="top">what a beautiful place to watch the sunrise, you''ve got some nice depth here</td>', 'what a beautiful place to watch the sunrise, you''ve got some nice depth here', '2010-04-07 09:54:40.000000', NULL, 1),
(5934997, 859740, 30049, '<td valign="top">Cute.  Good detail and I like the tension created with the people just off the edge.  Nice use of diagonals and triangulation.  Just some observations.  Good luck.</td>', 'Cute.  Good detail and I like the tension created with the people just off the edge.  Nice use of diagonals and triangulation.  Just some observations.  Good luck.', '2010-04-07 09:54:44.000000', NULL, 1),
(5935000, 863200, 73942, '<td valign="top">nice pose and pretty model, too bad the face seems to lack sharpness</td>', 'nice pose and pretty model, too bad the face seems to lack sharpness', '2010-04-07 09:55:29.000000', NULL, 1),
(5935001, 861980, 30049, '<td valign="top">Oooohhh...fun bokeh!  :-)  Amazing what you can get with a simple subject sometimes, eh?  Well done.</td>', 'Oooohhh...fun bokeh!  :-)  Amazing what you can get with a simple subject sometimes, eh?  Well done.', '2010-04-07 09:55:48.000000', NULL, 1),
(5935002, 863904, 30049, '<td valign="top">Looks like you had fun with this.  An interesting novelty shot.  Good luck.</td>', 'Looks like you had fun with this.  An interesting novelty shot.  Good luck.', '2010-04-07 09:56:36.000000', NULL, 1),
(5935008, 863581, 30049, '<td valign="top">Nice lighting effect at first glance.  Upon closer inspection it looks like a substantial amount of detail has been lost, especially in the arms, neck, and headwear.  Also getting some compression in the lower blues.</td>', 'Nice lighting effect at first glance.  Upon closer inspection it looks like a substantial amount of detail has been lost, especially in the arms, neck, and headwear.  Also getting some compression in the lower blues.', '2010-04-07 09:58:57.000000', NULL, 1),
(5935011, 863429, 30049, '<td valign="top">What a fun looking location.  Great timing to catch the rainbow and lovely lighting.  Good use of post to enhance, but not hurt, the end result.  Good luck in the challenge.</td>', 'What a fun looking location.  Great timing to catch the rainbow and lovely lighting.  Good use of post to enhance, but not hurt, the end result.  Good luck in the challenge.', '2010-04-07 10:00:20.000000', NULL, 1),
(5935012, 863165, 30049, '<td valign="top">That is a cool bird for sure.  The photo is quite busy (hard to pull out the subject).</td>', 'That is a cool bird for sure.  The photo is quite busy (hard to pull out the subject).', '2010-04-07 10:01:17.000000', NULL, 1),
(5935014, 864344, 30049, '<td valign="top">Unique.  Interesting choice for bg material (the circular pattern of the leaves work well with the sharp lines of the "Slug").</td>', 'Unique.  Interesting choice for bg material (the circular pattern of the leaves work well with the sharp lines of the "Slug").', '2010-04-07 10:02:32.000000', NULL, 1),
(5935015, 863733, 30049, '<td valign="top">Not quite as sharp as it could be (not terrible - it''s close).  Colors are a little neutral.</td>', 'Not quite as sharp as it could be (not terrible - it''s close).  Colors are a little neutral.', '2010-04-07 10:03:50.000000', NULL, 1),
(5935016, 864214, 30049, '<td valign="top">Ok, I guess.  Nothing personal, but the subject is a tad ho-humish IMO.  Good luck.</td>', 'Ok, I guess.  Nothing personal, but the subject is a tad ho-humish IMO.  Good luck.', '2010-04-07 10:04:33.000000', NULL, 1),
(5935020, 862891, 30049, '<td valign="top">Too busy.  Need to tone down the surrounding area to highlight your subject.  The leafless branches aren''t adding anything either.  I do like how you positioned the waterfall off-center.  Good luck.</td>', 'Too busy.  Need to tone down the surrounding area to highlight your subject.  The leafless branches aren''t adding anything either.  I do like how you positioned the waterfall off-center.  Good luck.', '2010-04-07 10:06:05.000000', NULL, 1),
(5935022, 864267, 30049, '<td valign="top">Good job of isolating the subject from the background.  You handled the tricky (contrasty) lighting pretty well (some blowout on the ears).  Nice tender moment captured.  Good luck.</td>', 'Good job of isolating the subject from the background.  You handled the tricky (contrasty) lighting pretty well (some blowout on the ears).  Nice tender moment captured.  Good luck.', '2010-04-07 10:07:15.000000', NULL, 1),
(5935027, 864396, 30049, '<td valign="top">Almost there.  Could''ve either increased the shutter speed to stop any minute movement, or stopped down one notch to increase the DOF slightly.  The dandelion seed head seems just slightly soft.  Perhaps a minor levels adjustment to bring up the contrast some.  I do like the bg bokeh.  Good luck.</td>', 'Almost there.  Could''ve either increased the shutter speed to stop any minute movement, or stopped down one notch to increase the DOF slightly.  The dandelion seed head seems just slightly soft.  Perhaps a minor levels adjustment to bring up the contrast some.  I do like the bg bokeh.  Good luck.', '2010-04-07 10:09:21.000000', NULL, 1),
(5935030, 859950, 30049, '<td valign="top">I like the B&amp;W conversion.  The comp works very well.  Some ghosting artifacts around the people from post work.  Don''t particularly care for the (wrongly) suggestive title...  All JMO of course.  Good luck in the challenge.</td>', 'I like the B&W conversion.  The comp works very well.  Some ghosting artifacts around the people from post work.  Don''t particularly care for the (wrongly) suggestive title...  All JMO of course.  Good luck in the challenge.', '2010-04-07 10:11:12.000000', NULL, 1),
(5935039, 864003, 30049, '<td valign="top">Uh-oh.  Hmmm...where to begin.  It''s colorful!  :-)  Not quite sharp.  Blue flare in lower left isn''t helpful, and it looks like some chromatic aberrations (hope I got that word correct...can never remember the exact term) in the upper tree branches.  Don''t give up.</td>', 'Uh-oh.  Hmmm...where to begin.  It''s colorful!  :-)  Not quite sharp.  Blue flare in lower left isn''t helpful, and it looks like some chromatic aberrations (hope I got that word correct...can never remember the exact term) in the upper tree branches.  Don''t give up.', '2010-04-07 10:13:51.000000', NULL, 1),
(5935054, 863408, 30049, '<td valign="top">The subjects are quite distant and not much to see in their "expression".  It does seem like they are looking at something on the ground near their feet.  ???  The scene overall is "ok".  I had to laugh at all of the foot tracks in the sand going back and forth to the couple.  :-)  Seeing some sensor dust spots in the sky, and the burning is a bit obvious (really noticeable in the upper-middle of the sky).  Just some observations, and obviously JMO.  Good luck.</td>', 'The subjects are quite distant and not much to see in their "expression".  It does seem like they are looking at something on the ground near their feet.  ???  The scene overall is "ok".  I had to laugh at all of the foot tracks in the sand going back and forth to the couple.  :-)  Seeing some sensor dust spots in the sky, and the burning is a bit obvious (really noticeable in the upper-middle of the sky).  Just some observations, and obviously JMO.  Good luck.', '2010-04-07 10:19:23.000000', NULL, 1),
(5935059, 862900, 30049, '<td valign="top">You tricked me!  :-)  At first glance I thought the graffiti was on the side of the train, yet the train seemed to be moving.  ???  I got it now.  :-)  Interesting (if not somewhat dangerous) location you selected for this shot.  Good luck.</td>', 'You tricked me!  :-)  At first glance I thought the graffiti was on the side of the train, yet the train seemed to be moving.  ???  I got it now.  :-)  Interesting (if not somewhat dangerous) location you selected for this shot.  Good luck.', '2010-04-07 10:20:54.000000', NULL, 1),
(5935066, 861525, 30049, '<td valign="top">Ansel Adams would be proud of this.  Great tonal range IMO and what wonderful detail!  In addition you''ve taken static subject material and really placed yourself well to great a dynamic comp.  One of my favorites in this months Free Study.  Bravo!</td>', 'Ansel Adams would be proud of this.  Great tonal range IMO and what wonderful detail!  In addition you''ve taken static subject material and really placed yourself well to great a dynamic comp.  One of my favorites in this months Free Study.  Bravo!', '2010-04-07 10:23:08.000000', NULL, 1),
(5935070, 863262, 30049, '<td valign="top">So then, where IS the most interesting place?  The middle of the road?  :-)  Selective desat doesn''t always work, but it does in this presentation.  Good luck.</td>', 'So then, where IS the most interesting place?  The middle of the road?  :-)  Selective desat doesn''t always work, but it does in this presentation.  Good luck.', '2010-04-07 10:24:27.000000', NULL, 1),
(5935074, 863177, 30049, '<td valign="top">Cute.  Unfortunately, you didn''t quite hit the mark on getting a focused, well exposed image.</td>', 'Cute.  Unfortunately, you didn''t quite hit the mark on getting a focused, well exposed image.', '2010-04-07 10:25:11.000000', NULL, 1),
(5935094, 863983, 30049, '<td valign="top">I don''t get this over the top, unnatural look.  Sorry.  I imagine she''s a very lovely lady, but you can''t tell in this shot.  Detail is gone, the eye liner/makeup looks choppy (can''t think of a better description, sorry), and it feels almost like a graphic rather than a photo overall.  One of the more interesting focal points for this IMO is the extreme lower-right where you can see some detail in her hair and fingers.  JMO of course.  Good luck.</td>', 'I don''t get this over the top, unnatural look.  Sorry.  I imagine she''s a very lovely lady, but you can''t tell in this shot.  Detail is gone, the eye liner/makeup looks choppy (can''t think of a better description, sorry), and it feels almost like a graphic rather than a photo overall.  One of the more interesting focal points for this IMO is the extreme lower-right where you can see some detail in her hair and fingers.  JMO of course.  Good luck.', '2010-04-07 10:33:28.000000', NULL, 1),
(5935097, 862467, 30049, '<td valign="top">Wonderful light!  You must have been ecstatic to see this scene unfold in front of you.</td>', 'Wonderful light!  You must have been ecstatic to see this scene unfold in front of you.', '2010-04-07 10:34:28.000000', NULL, 1),
(5935100, 864257, 30049, '<td valign="top">I really like how you caught just one wave (works well as a foreground, leading line element also).  The sky hanging just over the distant lighthouse is also very cool.  This is a fine example of minimalism, and a well balanced overall approach to the composition.  Well done!</td>', 'I really like how you caught just one wave (works well as a foreground, leading line element also).  The sky hanging just over the distant lighthouse is also very cool.  This is a fine example of minimalism, and a well balanced overall approach to the composition.  Well done!', '2010-04-07 10:36:43.000000', NULL, 1),
(5935120, 863805, 30049, '<td valign="top">Nice stop action shot.  These herons are spooked easily!</td>', 'Nice stop action shot.  These herons are spooked easily!', '2010-04-07 10:42:14.000000', NULL, 1),
(5935128, 859502, 30861, '<td valign="top">This is so excellent in so many ways... However, on my monitor at least you''ve totally posterized the reds/oranges int he sky to the point where it''s unacceptable; I wish you''d resisted the temptation. It''s a temptation I''ve fallen prey to many times in the past, and try to resist now.<br/> <br/>A 7 from me, would have been an 8 if the sky were more reasonable.</td>', 'This is so excellent in so many ways... However, on my monitor at least you''ve totally posterized the reds/oranges int he sky to the point where it''s unacceptable; I wish you''d resisted the temptation. It''s a temptation I''ve fallen prey to many times in the past, and try to resist now. A 7 from me, would have been an 8 if the sky were more reasonable.', '2010-04-07 10:43:34.000000', NULL, 1),
(5935143, 864217, 30049, '<td valign="top">Very pleasing photo and a fun moment you''ve captured here.  Makes a strong environmental portrait.  Overall nice processing (one observation is her shirt, pants, and the seat are grainy in spots...I get the impression you did some burning to tone down highlights perhaps?).  Nonetheless, it''s a wonderful photo.  Good luck in the challenge.</td>', 'Very pleasing photo and a fun moment you''ve captured here.  Makes a strong environmental portrait.  Overall nice processing (one observation is her shirt, pants, and the seat are grainy in spots...I get the impression you did some burning to tone down highlights perhaps?).  Nonetheless, it''s a wonderful photo.  Good luck in the challenge.', '2010-04-07 10:45:55.000000', NULL, 1),
(5935148, 863200, 86218, '<td valign="top">Nice portrait but it really seems soft in the eyes??</td>', 'Nice portrait but it really seems soft in the eyes??', '2010-04-07 10:46:43.000000', NULL, 1),
(5935149, 864275, 30049, '<td valign="top">It''s "ok".  Good color in the sky and near water reflection.  Somewhat neutral on the wow factor regarding subject material.  Good luck.</td>', 'It''s "ok".  Good color in the sky and near water reflection.  Somewhat neutral on the wow factor regarding subject material.  Good luck.', '2010-04-07 10:46:55.000000', NULL, 1),
(5935159, 864271, 30049, '<td valign="top">Overall, I like the photo.  The color of the horse sets off well from the surrounding neutral greys.  One consideration would be a slight burning of the edges of this presentation.  Just some observations.  Good luck.</td>', 'Overall, I like the photo.  The color of the horse sets off well from the surrounding neutral greys.  One consideration would be a slight burning of the edges of this presentation.  Just some observations.  Good luck.', '2010-04-07 10:48:12.000000', NULL, 1),
(5935172, 863751, 30861, '<td valign="top">This is actually quite outstanding. I''m not usually a fan of super-smooth, studio portraiture, but something about the expression and the raised eyebrow elevates this into "meaningfulness". I''d quibble with the hot spot on the earring, otherwise really well done.</td>', 'This is actually quite outstanding. I''m not usually a fan of super-smooth, studio portraiture, but something about the expression and the raised eyebrow elevates this into "meaningfulness". I''d quibble with the hot spot on the earring, otherwise really well done.', '2010-04-07 10:50:35.000000', NULL, 1),
(5935175, 864128, 30049, '<td valign="top">I think you worked WAY too hard in post trying to recover something that probably should have been reconsidered.  Subject is fine, but it''s very oversharpened and blurry.</td>', 'I think you worked WAY too hard in post trying to recover something that probably should have been reconsidered.  Subject is fine, but it''s very oversharpened and blurry.', '2010-04-07 10:50:49.000000', NULL, 1),
(5935180, 861819, 30049, '<td valign="top">Nice location.  Probably the wrong time of day to really maximize potential.  Light is a bit flat.</td>', 'Nice location.  Probably the wrong time of day to really maximize potential.  Light is a bit flat.', '2010-04-07 10:51:55.000000', NULL, 1),
(5935185, 863817, 30049, '<td valign="top">Nice layered kind of look with the various elements.  Perhaps a bit mundane for some.  Would work well in a series I think.  Good luck.</td>', 'Nice layered kind of look with the various elements.  Perhaps a bit mundane for some.  Would work well in a series I think.  Good luck.', '2010-04-07 10:52:41.000000', NULL, 1),
(5935195, 861970, 30049, '<td valign="top">I like the B&amp;W conversion.  Comp is fine.  May have lost some detail in the wingtips...overall a pleasing image.  Good luck.</td>', 'I like the B&W conversion.  Comp is fine.  May have lost some detail in the wingtips...overall a pleasing image.  Good luck.', '2010-04-07 10:54:19.000000', NULL, 1),
(5935201, 864402, 30049, '<td valign="top">Tricky photo to take.  You did a nice job combing multiple exposures to pull it off overall.</td>', 'Tricky photo to take.  You did a nice job combing multiple exposures to pull it off overall.', '2010-04-07 10:55:09.000000', NULL, 1),
(5935203, 863940, 86218, '<td valign="top">Pole a bit overexposed but nice angle you have here. Cute take</td>', 'Pole a bit overexposed but nice angle you have here. Cute take', '2010-04-07 10:55:32.000000', NULL, 1),
