INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5935608, 863981, 38162, '<td valign="top">chromatic abberation needs fixing in bridge (too much sharpening?).  nice composition and good concept.  gl</td>', 'chromatic abberation needs fixing in bridge (too much sharpening?).  nice composition and good concept.  gl', '2010-04-07 14:43:43.000000', NULL, 1),
(5935609, 864380, 30049, '<td valign="top">Ok.  Now if you''re going to shoot macro, shoot macro!  Hat''s off to you for getting good detail.  Very colorful and lots of texture to take in.</td>', 'Ok.  Now if you''re going to shoot macro, shoot macro!  Hat''s off to you for getting good detail.  Very colorful and lots of texture to take in.', '2010-04-07 14:44:51.000000', NULL, 1),
(5935610, 864184, 30049, '<td valign="top">What''d you take this with - a 600mm with a 2x converter?  :-)  I''m not saying that for any lack of quality...just for the proximity and closeness.</td>', 'What''d you take this with - a 600mm with a 2x converter?  :-)  I''m not saying that for any lack of quality...just for the proximity and closeness.', '2010-04-07 14:46:22.000000', NULL, 1),
(5935611, 863262, 38162, '<td valign="top">windy title not needed - its  in the picture!  great concept.</td>', 'windy title not needed - its  in the picture!  great concept.', '2010-04-07 14:46:32.000000', NULL, 1),
(5935612, 862943, 30049, '<td valign="top">Why is it a poet''s hand?  Looks like a naked lady to me.  I''ll bet the views are up substantially on this.  Sex sells.  Good luck.</td>', 'Why is it a poet''s hand?  Looks like a naked lady to me.  I''ll bet the views are up substantially on this.  Sex sells.  Good luck.', '2010-04-07 14:47:18.000000', NULL, 1),
(5935613, 861147, 30049, '<td valign="top">Ohhh...this is very nice!  A very intimate, inviting image.  Well done.</td>', 'Ohhh...this is very nice!  A very intimate, inviting image.  Well done.', '2010-04-07 14:47:56.000000', NULL, 1),
(5935614, 863577, 38162, '<td valign="top">do we need to know the age?  terrific concept here - adding the shades really makes this one!  gl  9</td>', 'do we need to know the age?  terrific concept here - adding the shades really makes this one!  gl  9', '2010-04-07 14:48:13.000000', NULL, 1),
