(5935617, 863795, 30049, '<td valign="top">Yep, it''s a flower.  :-)  A bit too bright for me.  Direct sunlight can be quite harsh.</td>', 'Yep, it''s a flower.  :-)  A bit too bright for me.  Direct sunlight can be quite harsh.', '2010-04-07 14:49:51.000000', NULL, 1),
(5935618, 863814, 30049, '<td valign="top">:-)  This is fun.  Great detail and good isolation of the subject.</td>', ':-)  This is fun.  Great detail and good isolation of the subject.', '2010-04-07 14:50:38.000000', NULL, 1),
(5935619, 863278, 30049, '<td valign="top">I like this.  Good POV, good color, right DOF.  Well done!</td>', 'I like this.  Good POV, good color, right DOF.  Well done!', '2010-04-07 14:51:23.000000', NULL, 1),
(5935622, 864196, 30049, '<td valign="top">Great choice and wonderful timing for capturing this photo.  Lovely lighting.</td>', 'Great choice and wonderful timing for capturing this photo.  Lovely lighting.', '2010-04-07 14:52:16.000000', NULL, 1),
