(5936378, 863780, 63218, '<td valign="top">I want to kick off my flipflops &amp; scamper barefoot thru this field of lilies. Maybe you took a big chance w/a border but it suits this comp. The coppery sky in the BG draws my eye right thru the flowers.</td>', 'I want to kick off my flipflops & scamper barefoot thru this field of lilies. Maybe you took a big chance w/a border but it suits this comp. The coppery sky in the BG draws my eye right thru the flowers.', '2010-04-07 22:29:48.000000', NULL, 1),
(5936419, 861548, 63218, '<td valign="top">seems very cold clear light, for the title, with some nice petal texture but to be homes the darkness on the L seems out of sync with the rest of the comp (JMO)</td>', 'seems very cold clear light, for the title, with some nice petal texture but to be homes the darkness on the L seems out of sync with the rest of the comp (JMO)', '2010-04-07 22:52:16.000000', NULL, 1),
