INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5938596, 864408, 30861, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> Heh!  I''m supposed to teach you?  You need Bear to teach you - he''s the master at photoshopping! </i></td></tr></table> <br/> <br/>No I''m not. But I did give this image an 8. Killer nice work :-)</td>', 'Originally posted by Melethia: Heh!  I''m supposed to teach you?  You need Bear to teach you - he''s the master at photoshopping!   No I''m not. But I did give this image an 8. Killer nice work :-)', '2010-04-09 12:12:18.000000', NULL, 0),
(5938597, 863429, 30861, '<td valign="top">This one got an 8 from me, it''s absolutely wonderful. Processing is spot on. The elevation of the mundane, always a hot-button for me :-)</td>', 'This one got an 8 from me, it''s absolutely wonderful. Processing is spot on. The elevation of the mundane, always a hot-button for me :-)', '2010-04-09 12:13:19.000000', NULL, 0),
(5938598, 863785, 30861, '<td valign="top">Got an 8 from me, one of my most favorites of the challenge. Gloriously evocative. Ridiculous finish, but you knew that would happen, right?</td>', 'Got an 8 from me, one of my most favorites of the challenge. Gloriously evocative. Ridiculous finish, but you knew that would happen, right?', '2010-04-09 12:15:15.000000', NULL, 0),
(5938600, 864132, 30861, '<td valign="top">I gave this an 8, which makes it one of my top scores in this challenge. The bleak &amp; angular sweep of it is breathtaking, the blue toning is an inspired choice. Well done!</td>', 'I gave this an 8, which makes it one of my top scores in this challenge. The bleak & angular sweep of it is breathtaking, the blue toning is an inspired choice. Well done!', '2010-04-09 12:17:26.000000', NULL, 0),
(5938629, 860141, 10686, '<td valign="top">I was pretty sure this would get a suck-ass score and I was right...whatever, I knew this shot wasn''t really DPC-esque when I submitted it. Anyway, I like it and the print is gorgeous. What else matters?<br/><br/><i>Message edited by author 2010-04-09 16:48:31.</i></td>', 'I was pretty sure this would get a suck-ass score and I was right...whatever, I knew this shot wasn''t really DPC-esque when I submitted it. Anyway, I like it and the print is gorgeous. What else matters?', '2010-04-09 13:05:52.000000', '2010-04-09 17:48:31.000000', 0),
(5938651, 864291, 61961, '<td valign="top">Sorry I didn''t get around to voting for all the entries this FS, I would have given this a high score for sure.</td>', 'Sorry I didn''t get around to voting for all the entries this FS, I would have given this a high score for sure.', '2010-04-09 13:25:36.000000', NULL, 0),
(5938655, 862976, 83313, '<td valign="top">I agree with <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=76335" rel="nofollow" target="_blank">bvy</a>, for the most part. You don''t want to kill a lot of the fine fluffy detail in something like this. You want to bring it out. A high radius unsharp mask is a good way of improving local contrast without killing detail. It can be used far more subtly and with more control than curves or the contrast adjustment. <a href="//www.ronbigelow.com/articles/articles.htm" rel="nofollow" target="_blank">Ron Bigelow</a> has a good series of articles on his site about how to use this for best effect.<br/> <br/></td>', 'I agree with  bvy, for the most part. You don''t want to kill a lot of the fine fluffy detail in something like this. You want to bring it out. A high radius unsharp mask is a good way of improving local contrast without killing detail. It can be used far more subtly and with more control than curves or the contrast adjustment. Ron Bigelow has a good series of articles on his site about how to use this for best effect. ', '2010-04-09 13:31:38.000000', NULL, 0),
(5938681, 864237, 71886, '<td valign="top">I didn''t vote in the challenge but I really like this shot.  Your focus is spot on.  I''m surprised it didn''t do better.  I think that your framing might be a little too tight around the head.  A little more space would open it up a bit.</td>', 'I didn''t vote in the challenge but I really like this shot.  Your focus is spot on.  I''m surprised it didn''t do better.  I think that your framing might be a little too tight around the head.  A little more space would open it up a bit.', '2010-04-09 14:32:05.000000', NULL, 0),
(5938709, 861576, 30791, '<td valign="top">Master of Lightning!!!</td>', 'Master of Lightning!!!', '2010-04-09 14:58:57.000000', NULL, 0),
(5938747, 862926, 61961, '<td valign="top">Wow, Brian.  I''ve tried "from the hip" a few times and my aim is terrible!  This is one of those photos that make me glad the photographer didn''t get caught.  Is that a cigarette or a blunt?<br/> <br/>I hate when I''ve left the camera on manual and think it''s on aperture priority.  I appreciate the street style, but I think it would have been retained the grit even with improved clarity and exposure.<br/> <br/></td>', 'Wow, Brian.  I''ve tried "from the hip" a few times and my aim is terrible!  This is one of those photos that make me glad the photographer didn''t get caught.  Is that a cigarette or a blunt? I hate when I''ve left the camera on manual and think it''s on aperture priority.  I appreciate the street style, but I think it would have been retained the grit even with improved clarity and exposure. ', '2010-04-09 16:12:47.000000', NULL, 0),
(5938756, 863607, 80096, '<td valign="top">Shame on you... for thinking outside the box and being uniquely creative... you should know better then to allow yourself to stray into such imaginative channels. Ten lashes for you for displaying your unwitting genius!! <br/> <br/>Jo ;-))<br/><br/><i>Message edited by author 2010-04-09 15:30:56.</i></td>', 'Shame on you... for thinking outside the box and being uniquely creative... you should know better then to allow yourself to stray into such imaginative channels. Ten lashes for you for displaying your unwitting genius!!  Jo ;-))', '2010-04-09 16:30:15.000000', '2010-04-09 16:30:56.000000', 0),
(5938770, 860141, 67697, '<td valign="top">This is awesome.  Love the oblique bokeh.  I''ve got to get a Lensbaby!</td>', 'This is awesome.  Love the oblique bokeh.  I''ve got to get a Lensbaby!', '2010-04-09 17:01:41.000000', NULL, 0),
(5938771, 864390, 14476, '<td valign="top"><b>Greetings from the Critique Club</b> <br/> <br/>What futuristic find you photographed.  Good one.  I really like the way you actually continued the ''in the future'' look with your colorful processing.  the cloud formations and sky coloring worked in your favor as well.<br/> <br/>I wonder if that dark shadow (another cloud?) in the lower right section of your image bothered your score?  Maybe the building just has that coloration or perhaps something else cast a shadow, but unexplained dark area may have been a distraction to our voting public.  <br/> <br/>It is an interesting building and you captured it well.<br/> <br/>Best regards,<br/> <br/>Alice</td>', 'Greetings from the Critique Club  What futuristic find you photographed.  Good one.  I really like the way you actually continued the ''in the future'' look with your colorful processing.  the cloud formations and sky coloring worked in your favor as well. I wonder if that dark shadow (another cloud?) in the lower right section of your image bothered your score?  Maybe the building just has that coloration or perhaps something else cast a shadow, but unexplained dark area may have been a distraction to our voting public.   It is an interesting building and you captured it well. Best regards, Alice', '2010-04-09 17:03:39.000000', NULL, 0),
(5938774, 859502, 46918, '<td valign="top">stunning image...congrats on a top 10</td>', 'stunning image...congrats on a top 10', '2010-04-09 17:11:43.000000', NULL, 0),
(5938789, 863607, 61961, '<td valign="top">I love this photo and title, and your photographer''s comments as well.  I''m sorry to hear you have been sick.  Feel better soon and keep up the good work (now let your wife make the purse). :-)</td>', 'I love this photo and title, and your photographer''s comments as well.  I''m sorry to hear you have been sick.  Feel better soon and keep up the good work (now let your wife make the purse). :-)', '2010-04-09 17:33:35.000000', NULL, 0),
(5938836, 859502, 22459, '<td valign="top">lovely image, congrats on the top ten finish and welcome back, good to see here again.</td>', 'lovely image, congrats on the top ten finish and welcome back, good to see here again.', '2010-04-09 18:46:58.000000', NULL, 0),
(5938879, 864112, 23484, '<td valign="top">Nice job on this.</td>', 'Nice job on this.', '2010-04-09 19:48:57.000000', NULL, 0),
(5938918, 864406, 76712, '<td valign="top">It''s a shame it did so bad :(<br/>it does lack sharpness and focus, and the lighting is a little blown out.<br/>BUT, it has a certain quality to it, its has great creativity and a good pose and i love the empty black space, it gives it a mysterious feel, which is helped by the title.<br/>I give you the HBROWN award, not only because of last place, but because it deserves a little more :)<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=866333" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/75000-79999/76712/120/Copyrighted_Image_Reuse_Prohibited_866333.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/75000-79999/76712/120/Copyrighted_Image_Reuse_Prohibited_866333.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/75000-79999/76712/120/Copyrighted_Image_Reuse_Prohibited_866333.gif"/></a></td>', 'It''s a shame it did so bad :(it does lack sharpness and focus, and the lighting is a little blown out.BUT, it has a certain quality to it, its has great creativity and a good pose and i love the empty black space, it gives it a mysterious feel, which is helped by the title.I give you the HBROWN award, not only because of last place, but because it deserves a little more :) ', '2010-04-09 20:37:01.000000', NULL, 0),
(5938926, 864406, 63812, '<td valign="top">Thank you, Josh! for your kind comment and for the HBROWN ...I really apreciate it. <br/></td>', 'Thank you, Josh! for your kind comment and for the HBROWN ...I really apreciate it. ', '2010-04-09 20:48:47.000000', NULL, 0),
(5939134, 863837, 100301, '<td valign="top">Nice work!</td>', 'Nice work!', '2010-04-10 01:15:51.000000', NULL, 0),
